INSERT INTO `attractions` (`id`, `destination_id`, `title`, `excerpt`, `full_desc`, `image`) VALUES
(1, 1, 'The Pyramids Of Giza & Sphinx', 'Of all of Egypt\'s major tourist attractions, only one is at the top of any list...', '<p>The Giza Plateau is home to the Great Pyramids of Cheops, Chephren, and Mykerinus. Built during the Fourth Dynasty of the Old Kingdom, the Great Pyramid of Cheops is the only surviving structure of the original Seven Wonders of the Ancient World.</p>\r\n<p>Guarding this magnificent complex is the Great Sphinx, a monumental statue with the body of a lion and the head of a pharaoh, widely believed to represent King Chephren.</p>', '1789274068_attr.jpeg'),
(2, 1, 'The Pyramids Of Sakkara', 'Sakkara (sometimes called Saqqara) is one section of the great necropolis of Memphis...', '<p>Located about 30 km south of Cairo, Sakkara was the vast necropolis of the ancient Egyptian capital, Memphis. Its absolute centerpiece is the Step Pyramid of Djoser, designed by the brilliant architect Imhotep.</p>\r\n<p>Built in the 27th century BC, it is considered the earliest colossal stone building and the earliest large-scale cut stone construction in history.</p>', '1789274008_attr.jpeg'),
(3, 1, 'The Pyramids Of Dahshur', 'Dahshour is one of Memphis\'s most important cemeteries...', '<p>Dahshur is a royal necropolis located in the desert on the west bank of the Nile. It is most famous for its two spectacular pyramids built by King Sneferu: the Bent Pyramid and the Red Pyramid.</p>\r\n<p>The Bent Pyramid is a unique transitional form with an angled top, representing a critical learning curve in pyramid building.</p>', '1789273719_attr.jpeg'),
(4, 1, 'The Open Air Museum Of Memphis', 'Memphis was the capital of ancient Egypt during the first dynasty...', '<p>Founded around 3100 BC by King Menes, Memphis was the first capital of a unified Egypt. Today, its ruins form a fascinating open-air museum set in a tranquil, palm-shaded village.</p><p>The absolute highlight of the museum is the breathtaking colossal statue of Ramses II. Carved from limestone, it measures over 10 meters long even without its lower legs.</p>', 'https://egypteyetour.com/wp-content/uploads/2018/09/Memphis.jpg'),
(5, 1, 'Cairo Tower', 'This city looks fascinating from above than what one sees from below...', '<p>Standing gracefully at 187 meters (614 feet), the Cairo Tower has been the tallest structure in Egypt and North Africa for decades. Located on Gezira Island, its striking lattice design is inspired by the lotus plant.</p><p>The observation deck at the very top offers unparalleled, breathtaking 360-degree panoramic views of the sprawling metropolis of Cairo.</p>', 'https://media.istockphoto.com/id/1276967305/photo/view-from-the-cairo-tower.jpg?s=612x612&w=0&k=20&c=7wYuwohb7bYOhaMpA6Kf3Js02KH6Vcw3OzrUhjLFve8='),
(6, 1, 'Museum Of Egyptian Antiquities', 'The museum contains the most important collection of Egyptian antiquities in the world...', '<p>Situated in the heart of Tahrir Square, the Museum of Egyptian Antiquities is home to one of the most extensive collections of ancient Egyptian artifacts in the world. Opened in 1902 in its distinct neoclassical building.</p><p>While many artifacts are moving to the GEM, this historic building remains an incredible labyrinth of ancient statues, mummies, and sarcophagi.</p>', 'https://news.artnet.com/app/news-upload/2025/06/grand-egyptian-museum-galleries-3-1024x768.jpg'),
(7, 1, 'The Citadel Of Saladin', 'The Citadel, situated on a highly visible part of the Mokattam Mountains...', '<p>Perched strategically on the Mokattam Hills, the Citadel of Saladin is a magnificent Islamic fortress. It was originally fortified by the great military leader Salah El-Din in 1176 to protect Cairo from Crusader attacks.</p><p>For nearly 700 years, it served as the royal residence and the seat of the Egyptian government.</p>', 'https://www.goldenluxortours.com/wp-content/uploads/2024/05/Citadel-Egypt-Golden-Luxor-tours.webp'),
(8, 1, 'The Mosque of Mohamed Ali', 'The Mohamed Ali Mosque, or the Alabaster Mosque, is one of Egypt\'s most interesting mosques...', '<p>Dominating the Cairo skyline from within the Citadel, the Mosque of Mohamed Ali is one of the city\'s most recognizable landmarks. Built between 1830 and 1848, it is famously known as the Alabaster Mosque.</p>\r\n<p>Its majestic Ottoman architecture, featuring a massive central dome and two towering, slender minarets, was heavily inspired by the grand mosques of Istanbul.</p>', '1789273962_attr.jpg'),
(9, 1, 'Sultan Hassan Madrassa & Mosque', 'The Sultan Hassan Madrassa is the Islamic world\'s most memorable monument...', '<p>A true masterpiece of Mamluk architecture, the Sultan Hassan Mosque and Madrassa was built between 1356 and 1363. Its massive scale, towering walls, and elegant proportions make it one of the largest in the world.</p>\r\n<p>It was designed not just as a place of worship, but to include schools (madrassas) for all four Sunni schools of Islamic law.</p>', '1789273863_attr.jpg'),
(10, 1, 'The Mosque Of Al Refaie', 'The mosque of Al Refaie is considered one of the most remarkable Islamic structures...', '<p>Located immediately opposite the monumental Sultan Hassan Mosque, the Al-Refaie Mosque was constructed much later, completed in 1912. Despite the time gap, it was meticulously designed to complement its older neighbor.</p>\r\n<p>The mosque serves as the royal mausoleum for the modern Egyptian royal family.</p>', '1789273903_attr.jpg'),
(11, 1, 'El-Azhar Mosque', 'Mosque of Al Azhar was the first Islamic University built in Cairo...', '<p>Founded in 970 AD during the Fatimid Caliphate, Al-Azhar Mosque is the first mosque established in Cairo, giving the city its title The City of a Thousand Minarets.</p>\r\n<p>Shortly after its founding, it became a center of learning, making Al-Azhar University one of the oldest continuously operating universities in the world.</p>', '1789273878_attr.jpg'),
(12, 1, 'Old Market Of Khan El-Khalili', 'The Khan El-Khalili is one of the most famous and oldest bazaars...', '<p>Khan El-Khalili is a sprawling, vibrant historic bazaar located in the heart of Islamic Cairo. Dating back to the 14th century, it was originally built as a caravanserai&mdash;a massive trading hub for traveling merchants.</p>\r\n<p>Today, its labyrinthine, narrow alleys are filled with shops selling everything from aromatic spices to intricate silver jewelry.</p>', '1789273609_attr.jpeg'),
(13, 1, 'The Hanging Church', 'Its name, Al-Muallaka (the hanging), was given to it since it was built on ruins...', '<p>Officially known as the Saint Virgin Mary\'s Coptic Orthodox Church, the Hanging Church gets its name from its unique location&mdash;it is built suspended entirely over the gatehouse of the ancient Roman Babylon Fortress.</p>\r\n<p>Dating back to the 3rd century, it is one of the oldest and most important churches in Egypt.</p>', '1789273221_attr.jpeg'),
(14, 1, 'St. Sergious And Bacchus Church', 'The church of St. Sergio is one of the sites visited by the Holy Family...', '<p>The Church of St. Sergius and Bacchus, locally known as Abu Serga, is a site of immense historical and religious significance in Old Cairo.</p>\r\n<p>According to strong local tradition, the church was built directly over the cavern where the Holy Family rested at the end of their flight into Egypt to escape King Herod.</p>', '1789273656_attr.jpg'),
(15, 1, 'Ben Ezra Synagogue', 'The Synagogue of Ben Ezra in Cairo was originally named El-Shamieen Church...', '<p>Located directly behind the Hanging Church in Old Cairo, the Ben Ezra Synagogue is a jewel of Egypt\'s Jewish heritage. According to local folklore, it marks the exact spot where the baby Moses was found in his basket.</p>\r\n<p>The synagogue gained worldwide fame in the late 19th century when an immense cache of ancient manuscripts was discovered in its storeroom.</p>', '1789273508_attr.jpg'),
(16, 1, 'The Pharaonic Village', 'The Pharaonic Village is a historic experience not to be missed...', '<p>Created by Dr. Hassan Ragab (the man who rediscovered the ancient art of papyrus making), the Pharaonic Village is a unique, interactive living museum that transports visitors back in time.</p>\r\n<p>Located on Jacob\'s Island in the Nile, visitors glide on motorized barges through a network of canals while actors in authentic ancient Egyptian costumes recreate scenes of daily life.</p>', '1789273489_attr.jpg'),
(17, 2, 'Luxor Temple', 'Situated on the east bank of the Nile River, this large Ancient Egyptian temple...', '<p>Located in the heart of the modern city on the east bank of the Nile, Luxor Temple is a stunning testament to the continuous history of Egypt. Unlike other temples in Thebes, it wasn\'t dedicated to a cult god.</p>\r\n<p>Constructed primarily by Amenhotep III and Ramesses II, with additions by Tutankhamun and Alexander the Great, the temple is famous for its grand colonnades.</p>', '1789273397_attr.jpg'),
(18, 2, 'The Temple of Karnak', 'The Karnak Temple Complex comprises a vast mix of decayed temples, chapels, pylons...', '<p>The Karnak Temple Complex is arguably the most astonishing religious site in the world. Developed over more than 2,000 years by successive pharaohs, it was the principal religious center of the god Amun-Re.</p>\r\n<p>The sheer scale of Karnak is overwhelming. Its crown jewel is the Great Hypostyle Hall&mdash;a breathtaking forest of 134 massive sandstone columns.</p>', '1789273331_attr.jpg'),
(19, 2, 'The Colossi of Memnon', 'Two massive stone statues of the Pharaoh Amenhotep III, standing at the front...', '<p>Standing like silent sentinels on the West Bank of Luxor, the Colossi of Memnon are two massive stone statues of Pharaoh Amenhotep III. For the past 3,400 years, they have sat here.</p>\r\n<p>Towering at 18 meters high and weighing roughly 720 tons each, the statues gained immense fame in antiquity when an earthquake caused one to crack.</p>', '1789273348_attr.jpg'),
(20, 2, 'The Valley Of The Kings', 'A valley where, for a period of nearly 500 years, rock-cut tombs were excavated...', '<p>Hidden within the arid cliffs of the Theban Necropolis on the West Bank lies the legendary Valley of the Kings. For nearly 500 years, this valley was the secret burial ground for the Pharaohs.</p>\r\n<p>Boasting over 60 excavated tombs&mdash;including those of Ramesses II, Seti I, and the famous boy-king Tutankhamun&mdash;the walls of these subterranean crypts are adorned with incredibly well-preserved scenes.</p>', '1789273633_attr.jpeg'),
(21, 2, 'The Valley Of The Queens', 'The burial site of the wives of pharaohs, known in ancient times as Ta-Set-Neferu...', '<p>Situated near the Valley of the Kings, the Valley of the Queens&mdash;known in ancient times as Ta-Set-Neferu (The Place of Beauty)&mdash;was the primary burial site for royal wives, princes, and princesses.</p>\r\n<p>The absolute highlight of this valley is the stunning Tomb of Queen Nefertari, the beloved Great Royal Wife of Ramesses II.</p>', '1789273166_attr.jpeg'),
(22, 2, 'The Temple Of Hatshepsut', 'Located at Deir El-Bahri, it is considered one of the incomparable monuments...', '<p>The Mortuary Temple of Queen Hatshepsut, located beneath the towering cliffs of Deir el-Bahari, is considered a masterpiece of ancient architecture. Designed by her architect Senenmut.</p>\r\n<p>As one of the most successful female pharaohs, Hatshepsut utilized the temple\'s brilliant reliefs to immortalize her divine birth and her famous trading expedition to the Land of Punt.</p>', '1789273129_attr.jpg'),
(23, 2, 'The Temple Of Dendera', 'One of the best-preserved temple complexes in Egypt, containing the Temple of Hathor...', '<p>Located north of Luxor, the Dendera Temple complex is one of the best-preserved in all of Egypt. The main structure, the Temple of Hathor (the goddess of love, joy, and beauty), was built largely during the Ptolemaic and Roman periods.</p>\r\n<p>Dendera is famous for its breathtaking, recently cleaned astronomical ceiling, which retains its vibrant blue colors.</p>', '1789273002_attr.jpg'),
(24, 2, 'The Temple Of Abydos', 'One of the most ancient cities of Upper Egypt, and also of the eighth nome...', '<p>Abydos is one of the oldest and holiest cities in ancient Egypt, revered as the cult center and burial place of Osiris, god of the underworld. The main attraction is the magnificent Temple of Seti I.</p>\r\n<p>The temple is celebrated for having some of the finest and most delicate bas-relief carvings in Egyptian art. It also houses the Abydos King List.</p>', '1789273052_attr.jpg'),
(25, 2, 'The Temple Of Medinet Habu', 'The Mortuary Temple of Ramesses III at Medinet Habu is an important structure...', '<p>Medinet Habu is the spectacular mortuary temple of Ramesses III. Second only to Karnak in size, it is widely considered the best-preserved New Kingdom temple in the Theban region.</p>\r\n<p>Approached through a massive, Syrian-style fortified gatehouse (the Migdol), the temple\'s massive walls are deeply incised with dramatic reliefs depicting Ramesses III\'s military victories.</p>', '1789272905_attr.jpg'),
(26, 2, 'The Temple Of Edfu', 'An Egyptian temple located on the west bank of the Nile in Edfu, dedicated to Horus...', '<p>Located between Luxor and Aswan, the Temple of Edfu is dedicated to the falcon god Horus. Built during the Ptolemaic period between 237 and 57 BC, it stands today as the most completely preserved temple in Egypt.</p>\r\n<p>Buried under desert sand and river silt for centuries, its massive 36-meter-high pylon gateway and immense inner sanctuary are perfectly intact.</p>', '1789272880_attr.jpeg'),
(27, 2, 'The Temple Of Kom Ombo', 'An unusual double temple built during the Ptolemaic dynasty, dedicated to Sobek and Horus...', '<p>Sitting picturesquely on a bend in the Nile River, Kom Ombo is an unusual double temple built during the Ptolemaic dynasty. The complex is perfectly symmetrical along its main axis.</p>\r\n<p>Fascinating highlights of the temple include a relief depicting ancient surgical instruments and medical tools, an ancient nilometer used to measure river levels, and a nearby museum housing mummified crocodiles.</p>', '1789272353_attr.jpg'),
(28, 3, 'The Unfinished Obelisk', 'The largest known ancient obelisk, providing incredible insight into the stone-working...', '<p>Located in the northern region of the stone quarries of ancient Egypt in Aswan, the Unfinished Obelisk provides an extraordinary, rare look into the stone-working techniques of the past.</p><p>Commissioned by Queen Hatshepsut, this obelisk would have been the heaviest and largest single piece of stone ever crafted by the Egyptians, weighing an estimated 1,200 tons.</p>', 'https://egypttravelsquare.com/3abar-data/uploads/2020/01/Unfinished-Obelisk-at-Aswan2.jpg'),
(29, 3, 'Aswan Botanical Island', 'Kitchener\'s Island is a quiet and beautiful oasis on the Nile River featuring...', '<p>Also known as Kitchener\'s Island, this lush oval-shaped island in the middle of the Nile is a tranquil oasis. It was given to Lord Horatio Kitchener in the 1890s as a reward for his military campaigns in Sudan.</p><p>With a deep passion for palm trees and plants, Kitchener transformed the entire island into a world-class botanical garden.</p>', 'https://egypttravelsquare.com/3abar-data/uploads/2020/01/The-Aswan-Botanical-Island.jpg'),
(30, 3, 'The High Dam', 'A marvel of modern engineering built in the 1960s to control the Nile\'s flooding...', '<p>Considered one of the greatest engineering feats of the 20th century, the Aswan High Dam was constructed between 1960 and 1970 to tame the unpredictable annual flooding of the Nile River.</p><p>The creation of this massive structure resulted in the formation of Lake Nasser, one of the world\'s largest artificial lakes.</p>', 'https://egypttravelsquare.com/3abar-data/uploads/2020/01/The-High-Dam.jpg'),
(31, 3, 'The Temples Of Abu Simbel', 'Two massive rock temples carved out of the mountainside during the reign of Pharaoh Ramesses II...', '<p>Carved entirely out of a solid sandstone mountain in southern Egypt, the Abu Simbel temples are a breathtaking monument to Pharaoh Ramesses II and his beloved queen, Nefertari.</p><p>In the 1960s, the entire complex was famously cut into massive blocks and relocated piece by piece to higher ground in a massive UNESCO-led effort to save it.</p>', 'https://egypttravelsquare.com/3abar-data/uploads/2019/12/egypt-aswan-day-trip-abu-simbel.jpg'),
(32, 3, 'Temple of Philae', 'An ancient island temple complex dedicated to the goddess Isis, relocated to Agilkia Island...', '<p>The Temple of Philae, dedicated primarily to the goddess Isis, is celebrated for its beautiful setting on an island in the Nile and its stunning Ptolemaic and Roman architecture.</p><p>Originally located on Philae Island, the temple was frequently flooded after the construction of the Aswan Low Dam. In an incredible rescue operation, UNESCO dismantled the entire complex and moved it to the nearby Agilkia Island.</p>', 'https://egypttravelsquare.com/3abar-data/uploads/2019/12/Philae-Temple-1.jpg'),
(33, 4, 'The Catacombs', 'Kom El-Shoukafa tomb is considered one of the Seven Wonders of the Middle Ages...', '<p>The Catacombs of Kom El Shoqafa are considered one of the Seven Wonders of the Middle Ages. Discovered accidentally in 1900 when a donkey fell into the access shaft.</p>\r\n<p>What makes this underground necropolis truly unique is its mesmerizing blend of ancient Egyptian, Greek, and Roman architectural and artistic styles.</p>', '1789272777_attr.jpeg'),
(34, 4, 'Pompey’s Pillar', 'The Memorial of Diocletian stands as a massive monolithic column towering over the ruins...', '<p>Standing tall amidst the ruins of the ancient Serapeum, Pompey\'s Pillar is a massive Roman triumphal column. Despite its name, which was mistakenly given by Crusaders.</p>\r\n<p>Carved from a single piece of red Aswan granite, it is one of the largest monolithic columns ever erected, measuring nearly 27 meters high.</p>', '1789272838_attr.jpg'),
(35, 4, 'The Qaitbay Citadel', 'Built on the exact site of the famous Lighthouse of Alexandria, this fortress offers...', '<p>The Citadel of Qaitbay is a stunning 15th-century defensive fortress located on the Mediterranean sea coast. It was established in 1477 AD by Sultan Al-Ashraf Sayf al-Din Qa\'it Bay.</p>\r\n<p>Most notably, the citadel was built on the exact site of the legendary Lighthouse of Alexandria (Pharos), one of the Seven Wonders of the Ancient World.</p>', '1789272814_attr.jpeg'),
(36, 4, 'Bibliotheca Alexandrina', 'The modern Library of Alexandria is a striking architectural masterpiece and a major cultural center...', '<p>The Bibliotheca Alexandrina is a striking modern architectural masterpiece, built to commemorate the original Great Library of Alexandria that was destroyed in antiquity.</p>\r\n<p>Its stunning granite exterior is carved with characters from 120 different human scripts. Inside, this vast cultural complex houses space for over 8 million books.</p>', '1789273035_attr.jpg'),
(37, 4, 'Roman Amphitheatre', 'Located in Kom El Dekka, it is the only Roman amphitheater discovered in Egypt...', '<p>Located in the heart of Alexandria at Kom El Dikka (Mound of Rubble), this is the only Roman amphitheatre ever discovered in Egypt. It was unearthed by accident in the 1960s.</p>\r\n<p>Dating back to the 2nd century AD, the well-preserved theatre features 13 semicircular tiers made of white marble that could seat up to 800 spectators.</p>', '1789274112_attr.jpg'),
(38, 4, 'Montaza Palace Gardens', 'A vast royal palace surrounded by lush, sprawling gardens overlooking the Mediterranean...', '<p>The Montaza Palace complex was built as a summer residence for the Egyptian royal family. Built in 1892 by Khedive Abbas II, the sprawling estate is perched on a low plateau overlooking a beautiful bay.</p>\r\n<p>The main attraction for visitors is the spectacular 150-acre royal gardens. Lush with rare pine trees, vibrant flower beds, and sweeping lawns.</p>', '1789274097_attr.jpg'),
(39, 4, 'National Museum Of Alexandria', 'Housed in a restored Italianate mansion, this museum guides you through the city\'s history...', '<p>Housed in a beautifully restored Italianate palace that once belonged to a wealthy wood merchant, the Alexandria National Museum offers an incredible journey through the history of the city.</p>\r\n<p>The basement is dedicated to the Pharaonic period, the ground floor covers the city\'s Greco-Roman prime, and the first floor showcases the Coptic and Islamic eras.</p>', '1789273019_attr.jpg'),
(40, 5, 'Ras Mohammed National Park', 'One of the most famous and pristine diving sites in the world...', '<p>Ras Mohammed is located at the southern extreme of the Sinai Peninsula. It is renowned globally for its spectacular coral reefs, diverse marine life, and crystal-clear waters, making it a paradise for snorkelers and divers.</p>', '1789272486_attr.jpg'),
(41, 5, 'Tiran Island', 'A breathtaking island famous for its crystal clear waters and coral reefs...', '<p>Named after Tiran Island, the Straits of Tiran are the narrow sea passages between Sinai and the Arabian peninsulas. It features four main reefs (Gordon, Thomas, Woodhouse, and Jackson) which are among the best-preserved in the entire Red Sea.</p>', '1789272534_attr.jpg'),
(42, 5, 'Naama Bay', 'The vibrant heart of Sharm El Sheikh, filled with cafes, restaurants, and bazaars...', '<p>Naama Bay is the bustling center of Sharm El Sheikh. With its long sandy beaches, extensive promenade, and endless array of dining and entertainment options, it is the perfect place to relax during the day and explore at night.</p>', '1789272504_attr.jpg'),
(43, 5, 'Saint Catherine Monastery', 'The oldest continuously inhabited Christian monastery in the world...', '<p>Located 220 km northwest of Sharm el Sheikh between the St-Catherine mountains and Mount Sinai, this Orthodox Greek monastery is incredibly rich in religious history. It houses a library of ancient manuscripts second only to the Vatican.</p>', '1789272519_attr.jpg');
INSERT INTO `destinations` (`id`, `name`, `slug`, `hero_image`, `intro_title`, `intro_text`) VALUES
(1, 'Cairo', 'cairo', 'https://media.istockphoto.com/id/1276967305/photo/view-from-the-cairo-tower.jpg?s=612x612&w=0&k=20&c=7wYuwohb7bYOhaMpA6Kf3Js02KH6Vcw3OzrUhjLFve8=', 'Welcome to the City of a Thousand Minarets', '<p>Cairo is the capital of Egypt and the largest city in Africa, its name means “the victorious one.” A trip to Egypt is not complete without a visit to this sprawling metropolis along the banks of the river Nile.</p>'),
(2, 'Luxor', 'luxor', '1789275249_dest.jpg', 'Journey Back to Ancient Times', '<p>Luxor is often called the world\'s greatest open-air museum. The number and preservation of the monuments in the Luxor area are unparalleled anywhere else in the world.</p>'),
(4, 'Alexandria', 'alexandria', '1789275261_dest.jpg', 'The Pearl of the Mediterranean', '<p>The city of Alexandria was founded by Alexander the Great in 333 B.C. In Alexandria, there are many magnificent sightseeing spots to explore reflecting its unique Greek, Roman, and Egyptian heritage.</p>'),
(5, 'Sharm El Sheikh', 'sharm-el-sheikh', '1789275277_dest.jpg', 'The City of Peace', '<p>Egypt Travel Square arranges tours and excursions in Sharm El Sheikh whether you look for sea tours and Snorkeling trips, Diving, Watching dolphin shows, or Spending a wonderful day in Aqua Park.</p>'),
(8, 'Aswan', 'aswan', '1789275046_dest.jpg', 'Aswan', '<div class=\"tox tox-tinymce\" role=\"application\" aria-disabled=\"false\">\r\n<div class=\"tox-editor-container\">\r\n<div class=\"tox-editor-header\" data-alloy-vertical-dir=\"toptobottom\">\r\n<div class=\"tox-anchorbar\">&nbsp;</div>\r\n</div>\r\n<div class=\"tox-sidebar-wrap\">\r\n<p><span style=\"color: rgb(224, 62, 45);\"><strong>Aswan Day Excursions and tours</strong></span>, from Aswan you can spend an unforgettable time visiting the most magnificent city overlooking the River Nile. Which is the most famous winter resort in the world with its warm charming nature.It&nbsp;is situated at the foot of the Nile Valley to the North end of Lake Nasser.</p>\r\n<div class=\"show_more\">\r\n<div class=\"wpsm-content\"><span style=\"color: rgb(224, 62, 45);\"><strong>Aswan</strong></span> is the capital of its own governorate and has a population of about 1.2 million. Most of the city&rsquo;s residents are Nubians and local tribes of the Kenzo people&nbsp;\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: rgb(224, 62, 45);\"><strong>Aswan </strong></span>takes its name from the ancient Egyptian word &ldquo;swan&rdquo;, meaning &ldquo;the market&rdquo;. This is because it was located on the main trade route between Egypt and the southern lands, bringing gold, slaves and ivory into Egypt. The governors of the 6th Dynasty sent many expeditions to explore the many African countries located to the south, and most of these started from Aswan. It was also the major source of granite, sandstone, and quartzite used in the construction of&nbsp;various major monuments throughout Egypt.Aswan Tours allows you to enjoy the shining sun reflecting on the Nile River at its best flowing through the famous granite rocks in Aswan. Book Aswan Tours with Emo Tours and spend a wonderful time visiting the most famous archaeological sites in Aswan whether you want a day tour to Philae Temple and High Dam or Day tour to Abu Simbel Temple from Aswan or Day tour to Luxor From Aswan and more.<strong><span style=\"color: rgb(224, 62, 45);\">Egypt travel square</span></strong> makes it simple to find endless Aswan vacation ideas just check our Tours list below and you can sort our offers with the things you want to do and may you have any special requirements not mentioned in our tours list please don&rsquo;t hesitate to contact us and let us know what exactly you want to do.</p>\r\n<p><strong>&bull; Please read the following notes before you start the booking :<br></strong></p>\r\n<p>* All daytime tourist highlights are open all the week from 8:00 am to 4:00 pm daily<br>* Tourist highlights are selected as a maximum of 3 tourist highlights for Full day tour and a minimum of 2 tourist highlights for half day tour .. In case of request tourist highlights more than three visits or less than two visits please contact us before you start booking to give you more advises on Email / info@egypttravelsquare.com<br>* The tour Duration of the day tour is 8 hours (including the pickup &amp; the drop off)<br>* The Day tour to Abu Simple from Aswan by Car would be starting pick up at4:00am (Duration: 9 Hours) &amp; drop off at Aswan around 1:00pm<br>Please note that the day tour to Abu Simple from Aswan by Car is Required details during Booking Process to get the trip permission from the Tourism Police BEFORE 24 HOURS as the following<br>1. Full names of all travelers<br>2. Nationalities<br>3. passports Numbers</p>\r\n<p>Please make sure to advise this details in the Special Require Box<br>* The Day Tour to Edfu and Kom ombo Temples from Aswan would be starting pick up at 7:00am (Duration: 9 Hours) &amp; drop off at Aswan around 4:00pm<br>* All Pick up &amp; drop off for clients in the day tour will be from Hotels ONLY in Aswan city &hellip; In case of a request to Pick up &amp; drop off from a private residence please advise the address in clear detail in the hotel pick up &amp; drop off box<br>* You can arrange Aswan Layover tour from Aswan airport As the one day tour. But the pickup &amp; drop off (from/to) Aswan airport is not including &hellip; To add it please select *Add pick up &amp; drop off (from/to) Aswan airport* from the booking form&hellip; Please make sure to advise the arrival flight details in the Special Require Box as the following (Airline company name &ndash; Flight No.- Arrival time &amp; date) and Once you arrive to Aswan airport just pass the only exit gate of the terminal ( Outside the Terminal ) you will find our tour guide holding a sign shown your name<br>* Lunch is not including at the day tour &hellip; To add the lunch please select *Add Lunch at restaurants* from the booking form. The Lunch is budget based on the full meal for each person, but the drinks are not included<br>* This booking form is used for a one day tour only &hellip; To book another day tour you must fill out a new booking form to ensure that you receive the discount in each booking<br>* All prices mentioned are Quoted Per Person in U.S Dollars ($) and the payment will be at the End of the tour in U.S.D cash OR what equivalent of the international currencies (GBP &ndash; EUR &ndash; CAD &ndash; AUD &ndash; NZD &ndash; SAR &ndash; AED) Even by Egyptian pound according to the bank rate &hellip; If you intend to paid by the credit card there would be 3% to be added on the grand total</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>'),
(9, 'Giza', 'giza', '1789354154_dest.jpeg', 'Giza', '<p>Of all of Egypt&rsquo;s major tourist attractions, only one is at the.<strong>&nbsp;The Great Pyramids and Sphinx</strong><br>On the outskirts of Cairo, stands one of the Seven Wonders of the ancient World: the great pyramids. Built around 4.500 years ago, the three towering pyramids are massive in size, constructed from around 2,300,000 blocks, weighing an average of two-and-a-half tons each. Within short walking distance of the pyramids is the great sphinx of Giza, built in 2620 BC in the likeness of the King of Egypt Chephran, (Khafre). The ancient monument- 187 feet long and 65 feet high is a human headed lion wearing a royal headdress, sitting in guard of the great pyramids.</p>');
INSERT INTO `faqs` (`id`, `question`, `answer`) VALUES
(1, 'Is it Safe to Travel to Egypt Now?', 'Yes, it is very safe. The best way to answer this is to review recent feedback on platforms like TripAdvisor from visitors who just left Egypt. The police, tourist police, and army are always close by, and the Egyptian people are incredibly friendly, welcoming, and protective of tourists.'),
(2, 'How do I get my tourist visa?', 'If you are from North America, Western Europe, Australia/New Zealand, Brazil/Argentina, Japan, or Singapore, you can easily get your tourist visa upon arrival at the airport in Egypt. Other nationalities usually need to apply to their local Egyptian Embassy or Consulate prior to travel.'),
(3, 'What is the best time to travel to Egypt?', 'The peak and most comfortable time to visit is from October to May when temperatures are mild. However, summer (May to October) offers a virtual peace and quiet with significantly fewer crowds at major sites, and great discounts, provided you can handle the heat!'),
(4, 'What about traveling during Ramadan?', 'Ramadan is a superb, festival-like month. While Muslims fast during the day, restaurants and cafes still cater to tourists. Sites close slightly earlier, but after sunset, the country comes alive with lights, food, and celebration. It is an unforgettable cultural experience.'),
(5, 'How should I dress for entering a mosque?', 'Protocol asks that men wear long trousers rather than shorts. Women should cover bare skin as much as possible—shoulders and legs must be covered. While covering the head is not strictly legally required in all tourist mosques, it is a highly appreciated sign of respect (a simple scarf will suffice).'),
(6, 'Can I take photographs inside the tombs?', 'No, photography inside ancient tombs (including inside the Pyramids and Abu Simbel) is strictly forbidden to protect the ancient paintwork from excessive flash damage. Cameras are perfectly fine outside the sites!'),
(7, 'Is it safe for women to travel alone?', 'Yes. Many solo female travelers visit Egypt and feel completely safe. However, as with any global destination, take standard precautions: avoid deserted areas at night and stick to reputable taxis or booked tours.'),
(8, 'Do I need to take anti-malaria tablets?', 'NO! Malaria has not been in Egypt for over 85 years. Taking unnecessary anti-malaria medication can cause side effects that might ruin your holiday. Stick to drinking bottled water to avoid minor stomach upsets from the local tap water.');
